# --- incidentzero.telemetry.budget.BudgetManager ---

def test_budget_manager_initialization_defaults():
    budget_manager = BudgetManager()
    assert budget_manager.remaining_llm == 14
    assert budget_manager.remaining_tools == 28

def test_budget_manager_initialization_custom():
    budget_manager = BudgetManager(max_llm_calls=5, max_tool_calls=10)
    assert budget_manager.remaining_llm == 5
    assert budget_manager.remaining_tools == 10

def test_budget_manager_consume_llm_success():
    budget_manager = BudgetManager(max_llm_calls=2)
    budget_manager.consume_llm()
    assert budget_manager.remaining_llm == 1
    budget_manager.consume_llm()
    assert budget_manager.remaining_llm == 0

def test_budget_manager_consume_llm_exceeded():
    budget_manager = BudgetManager(max_llm_calls=1)
    budget_manager.consume_llm()
    assert budget_manager.remaining_llm == 0
    with pytest.raises(BudgetExceeded):
        budget_manager.consume_llm()
    assert budget_manager.remaining_llm == 0 # Counter does not change

def test_budget_manager_consume_tool_success():
    budget_manager = BudgetManager(max_tool_calls=2)
    budget_manager.consume_tool()
    assert budget_manager.remaining_tools == 1
    budget_manager.consume_tool()
    assert budget_manager.remaining_tools == 0

def test_budget_manager_consume_tool_exceeded():
    budget_manager = BudgetManager(max_tool_calls=1)
    budget_manager.consume_tool()
    assert budget_manager.remaining_tools == 0
    with pytest.raises(BudgetExceeded):
        budget_manager.consume_tool()
    assert budget_manager.remaining_tools == 0 # Counter does not change

# --- incidentzero.agent.recovery.RetryPolicy ---

class MockSleeper:
    def __init__(self):
        self.calls = []

    def __call__(self, delay: float):
        self.calls.append(delay)

def test_retry_policy_call_model_success_first_attempt():
    sleeper = MockSleeper()
    policy = RetryPolicy(max_attempts=3, sleeper=sleeper)
    mock_fn = Mock(return_value="success")

    result = policy.call_model(mock_fn)

    assert result == "success"
    mock_fn.assert_called_once()
    assert not sleeper.calls

def test_retry_policy_call_model_transient_success_after_retry():
    sleeper = MockSleeper()
    policy = RetryPolicy(max_attempts=3, sleeper=sleeper)
    mock_fn = Mock()
    mock_fn.side_effect = [
        TransientModelError("fail 1"),
        TransientModelError("fail 2"),
        "success"
    ]

    result = policy.call_model(mock_fn)

    assert result == "success"
    assert mock_fn.call_count == 3
    assert sleeper.calls == [1.0, 2.0] # 1s after 1st fail, 2s after 2nd fail

def test_retry_policy_call_model_transient_failure_max_attempts():
    sleeper = MockSleeper()
    policy = RetryPolicy(max_attempts=3, sleeper=sleeper)
    mock_fn = Mock(side_effect=TransientModelError("always fail"))

    with pytest.raises(TransientModelError, match="always fail"):
        policy.call_model(mock_fn)

    assert mock_fn.call_count == 3
    assert sleeper.calls == [1.0, 2.0] # No wait after final failed attempt

def test_retry_policy_call_model_permanent_error_no_retry():
    sleeper = MockSleeper()
    policy = RetryPolicy(max_attempts=3, sleeper=sleeper)
    mock_fn = Mock(side_effect=PermanentModelError("permanent fail"))

    with pytest.raises(PermanentModelError, match="permanent fail"):
        policy.call_model(mock_fn)

    mock_fn.assert_called_once()
    assert not sleeper.calls

def test_retry_policy_call_model_other_exception_no_retry():
    sleeper = MockSleeper()
    policy = RetryPolicy(max_attempts=3, sleeper=sleeper)
    mock_fn = Mock(side_effect=ValueError("some other error"))

    with pytest.raises(ValueError, match="some other error"):
        policy.call_model(mock_fn)

    mock_fn.assert_called_once()
    assert not sleeper.calls

def test_retry_policy_max_attempts_one():
    sleeper = MockSleeper()
    policy = RetryPolicy(max_attempts=1, sleeper=sleeper)
    mock_fn = Mock(side_effect=TransientModelError("fail"))

    with pytest.raises(TransientModelError, match="fail"):
        policy.call_model(mock_fn)

    assert mock_fn.call_count == 1
    assert not sleeper.calls

# --- incidentzero.agent.policies.LoopGuard ---

def test_loop_guard_default_max_repeats():
    guard = LoopGuard() # default max_same_action_repeats=2
    action = ("get_logs", {"service": "api", "limit": 5})

    assert not guard.record(*action) # 1st time
    assert not guard.record(*action) # 2nd time
    assert guard.record(*action)     # 3rd time, exceeds limit

def test_loop_guard_custom_max_repeats():
    guard = LoopGuard(max_same_action_repeats=1)
    action = ("restart_service", {"name": "web"})

    assert not guard.record(*action) # 1st time
    assert guard.record(*action)     # 2nd time, exceeds limit

def test_loop_guard_different_actions_counted_separately():
    guard = LoopGuard(max_same_action_repeats=1)
    action1 = ("get_logs", {"service": "api"})
    action2 = ("get_metrics", {"service": "db"})

    assert not guard.record(*action1)
    assert not guard.record(*action2)
    assert guard.record(*action1) # action1 repeats
    assert guard.record(*action2) # action2 repeats

def test_loop_guard_arguments_compared_by_value_order_independent():
    guard = LoopGuard(max_same_action_repeats=1)
    action_name = "update_config"
    args1 = {"key": "value", "id": 123}
    args2 = {"id": 123, "key": "value"} # Same as args1, different order

    assert not guard.record(action_name, args1)
    assert guard.record(action_name, args2) # Should count as a repeat

def test_loop_guard_arguments_different_values():
    guard = LoopGuard(max_same_action_repeats=1)
    action_name = "update_config"
    args1 = {"key": "value1"}
    args2 = {"key": "value2"}

    assert not guard.record(action_name, args1)
    assert not guard.record(action_name, args2) # Not a repeat
    assert guard.record(action_name, args1) # args1 repeats

def test_loop_guard_world_version_resets_counts():
    guard = LoopGuard(max_same_action_repeats=1)
    action = ("get_status", {"id": "1"})

    assert not guard.record(*action, current_world_version=1) # 1st time, world 1
    assert guard.record(*action, current_world_version=1)     # 2nd time, world 1, exceeds limit

    # World version changes, counts should reset
    assert not guard.record(*action, current_world_version=2) # 1st time, world 2
    assert guard.record(*action, current_world_version=2)     # 2nd time, world 2, exceeds limit

def test_loop_guard_world_version_no_change_does_not_reset():
    guard = LoopGuard(max_same_action_repeats=1)
    action = ("get_status", {"id": "1"})

    assert not guard.record(*action, current_world_version=1) # 1st time, world 1
    assert guard.record(*action, current_world_version=1)     # 2nd time, world 1, exceeds limit

    # Record again with same world version, should still be considered a repeat
    assert guard.record(*action, current_world_version=1)

def test_loop_guard_world_version_none_does_not_reset():
    guard = LoopGuard(max_same_action_repeats=1)
    action = ("get_status", {"id": "1"})

    assert not guard.record(*action) # 1st time, no world version
    assert guard.record(*action)     # 2nd time, no world version, exceeds limit

    # Record again with no world version, should still be considered a repeat
    assert guard.record(*action)

def test_loop_guard_world_version_mix_none_and_value():
    guard = LoopGuard(max_same_action_repeats=1)
    action = ("get_status", {"id": "1"})

    assert not guard.record(*action, current_world_version=1)
    assert guard.record(*action, current_world_version=1)

    # Now record without world version, should not reset
    assert guard.record(*action)

    # Now record with a different world version, should reset
    assert not guard.record(*action, current_world_version=2)
    assert guard.record(*action, current_world_version=2)


# --- incidentzero.agent.policies.ReplanPolicy ---

@pytest.fixture
def replan_policy():
    return ReplanPolicy()

@pytest.mark.parametrize("status, retryable, expected_evaluation", [
    ("ok", False, "continue"),
    ("ok", True, "continue"), # retryable doesn't matter for "ok"

    ("loop_detected", False, "replan"),
    ("loop_detected", True, "replan"),
    ("approval_denied", False, "replan"),
    ("approval_denied", True, "replan"),
    ("validation_error", False, "replan"),
    ("validation_error", True, "replan"),
    ("stale_precondition", False, "replan"),
    ("stale_precondition", True, "replan"),

    ("temporary_error", True, "retry"),
    ("rate_limit", True, "retry"),

    ("error", False, "replan"),
    ("error", True, "replan"), # retryable doesn't matter for "error"
    ("failed", False, "replan"),
    ("unknown_status", False, "replan"),
    ("another_status", True, "replan"), # unknown status, retryable true, still replan
])
def test_replan_policy_evaluate(replan_policy, status, retryable, expected_evaluation):
    tool_result = {"status": status, "retryable": retryable}
    assert replan_policy.evaluate(tool_result) == expected_evaluation

@pytest.mark.parametrize("status, retryable, expected_should_replan", [
    ("ok", False, False),
    ("loop_detected", False, True),
    ("approval_denied", True, True),
    ("validation_error", False, True),
    ("stale_precondition", True, True),
    ("temporary_error", True, False), # retry, not replan
    ("error", False, True),
    ("unknown_status", False, True),
])
def test_replan_policy_should_replan(replan_policy, status, retryable, expected_should_replan):
    tool_result = {"status": status, "retryable": retryable}
    assert replan_policy.should_replan(tool_result) == expected_should_replan


