def test_agent_state_initialization():
    state = AgentState(plan=AgentPlan(steps=[]), current_step_idx=0, incident_observation={}, context=[])
    assert state.evidence_ids == []
    assert state.latest_world_version is None
    assert len(state.last_tool_results) == 0

def test_agent_state_observe_result_with_evidence_id():
    state = AgentState(plan=AgentPlan(steps=[]), current_step_idx=0, incident_observation={}, context=[])
    result1 = {"evidence_id": "id1", "status": "ok"}
    result2 = {"evidence_id": "id2", "status": "ok"}
    result3 = {"status": "ok"} # No evidence_id

    state.observe_result(result1)
    assert state.evidence_ids == ["id1"]
    state.observe_result(result2)
    assert state.evidence_ids == ["id1", "id2"]
    state.observe_result(result3)
    assert state.evidence_ids == ["id1", "id2"] # No change

def test_agent_state_observe_result_with_world_version():
    state = AgentState(plan=AgentPlan(steps=[]), current_step_idx=0, incident_observation={}, context=[])
    result1 = {"world_version": 1, "status": "ok"}
    result2 = {"world_version": 5, "status": "ok"}
    result3 = {"world_version": "invalid", "status": "ok"} # Non-integer
    result4 = {"status": "ok"} # No world_version

    state.observe_result(result1)
    assert state.latest_world_version == 1
    state.observe_result(result2)
    assert state.latest_world_version == 5
    state.observe_result(result3)
    assert state.latest_world_version == 5 # Unchanged
    state.observe_result(result4)
    assert state.latest_world_version == 5 # Unchanged

def test_agent_state_observe_result_last_tool_results_limit():
    state = AgentState(plan=AgentPlan(steps=[]), current_step_idx=0, incident_observation={}, context=[])

    # Add 8 results
    for i in range(8):
        state.observe_result({"status": "ok", "data": f"result_{i}"})
    assert len(state.last_tool_results) == 8
    assert state.last_tool_results[0]["data"] == "result_0"
    assert state.last_tool_results[7]["data"] == "result_7"

    # Add 9th result, first one should be dropped
    state.observe_result({"status": "ok", "data": "result_8"})
    assert len(state.last_tool_results) == 8
    assert state.last_tool_results[0]["data"] == "result_1"
    assert state.last_tool_results[7]["data"] == "result_8"

    # Add 10th result
    state.observe_result({"status": "ok", "data": "result_9"})
    assert len(state.last_tool_results) == 8
    assert state.last_tool_results[0]["data"] == "result_2"
    assert state.last_tool_results[7]["data"] == "result_9"

def test_agent_state_observe_result_all_fields():
    state = AgentState(plan=AgentPlan(steps=[]), current_step_idx=0, incident_observation={}, context=[])
    result = {
        "status": "ok",
        "evidence_id": "test-id",
        "world_version": 10,
        "data": {"key": "value"},
        "message": "success"
    }
    state.observe_result(result)
    assert state.evidence_ids == ["test-id"]
    assert state.latest_world_version == 10
    assert len(state.last_tool_results) == 1
    assert state.last_tool_results[0] == result


# --- incidentzero.telemetry.trace.TraceRecorder ---

def test_trace_recorder_initialization_creates_file_and_parents(tmp_path):
    trace_file = tmp_path / "logs" / "trace.jsonl"
    recorder = TraceRecorder(trace_file)
    assert trace_file.exists()
    assert trace_file.read_text() == ""
    assert trace_file.parent.is_dir()

def test_trace_recorder_record_appends_json_line(tmp_path):
    trace_file = tmp_path / "trace.jsonl"
    recorder = TraceRecorder(trace_file)

    event1 = "start_agent"
    payload1 = {"incident_id": "inc-123"}
    with patch('time.time', return_value=1678886400.0): # Mock timestamp
        recorder.record(event1, payload1)

    event2 = "tool_call"
    payload2 = {"tool": "get_metrics", "args": {"service": "api"}}
    with patch('time.time', return_value=1678886401.5): # Mock timestamp
        recorder.record(event2, payload2)

    content = trace_file.read_text().strip().split('\n')
    assert len(content) == 2

    line1 = json.loads(content[0])
    assert line1["ts"] == 1678886400.0
    assert line1["event"] == event1
    assert line1["payload"] == payload1

    line2 = json.loads(content[1])
    assert line2["ts"] == 1678886401.5
    assert line2["event"] == event2
    assert line2["payload"] == payload2

def test_trace_recorder_record_empty_payload(tmp_path):
    trace_file = tmp_path / "trace.jsonl"
    recorder = TraceRecorder(trace_file)

    event = "heartbeat"
    payload = {}
    with patch('time.time', return_value=1234567890.0):
        recorder.record(event, payload)

    content = trace_file.read_text().strip()
    line = json.loads(content)
    assert line["ts"] == 1234567890.0
    assert line["event"] == event
    assert line["payload"] == payload
